mapper.select:
SELECT
	COUNT(*)
FROM 
	CMS_MEDIAFACTORY
WHERE 
	1=1
AND	homepage_id = #{homepage_id}
AND	date_type = #{date_type}
AND use_time = #{use_time}
AND start_date = #{start_date}
AND	(
		(start_time  <  #{start_time} AND end_time > #{start_time})
	OR	(start_time  <  #{end_time} AND end_time > #{end_time})
	)
